function makeSession(
	id: string,
	overrides: Partial<SessionMetadata> = {},
): SessionMetadata {
	return {
		id,
		title: `Session ${id}`,
		parentSessionId: null,
		forkedAt: undefined,
		createdAt: `2026-07-01T0${id}:00:00.000Z`,
